def minTotalDistance(houses, k):
    a = sorted(houses)
    n = len(a)
    P = [0] * (n + 1)
    for i, x in enumerate(a):
        P[i + 1] = P[i] + x
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i, n):
            m = (i + j) // 2
            C[i][j] = a[m] * (m - i) - (P[m] - P[i]) + (P[j + 1] - P[m + 1]) - a[m] * (j - m)
    INF = 10 ** 18
    prev = [INF] * (n + 1)
    prev[0] = 0
    for g in range(1, k + 1):
        cur = [INF] * (n + 1)
        for i in range(g, n + 1):
            best = INF
            for t in range(g - 1, i):
                v = prev[t] + C[t][i - 1]
                if v < best:
                    best = v
            cur[i] = best
        prev = cur
    return prev[n]
